// How many games took each number of turns, with the average marked in red.
const turns = nb.get('turns') ?? [];
const games = turns.reduce((sum, t) => sum + t.games, 0);
const average = games ? turns.reduce((sum, t) => sum + t.turns * t.games, 0) / games : 0;

return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  title: 'How many turns does a game take?',
  width: 620,
  height: 260,
  layer: [
    {
      data: { values: turns },
      mark: { type: 'bar', color: '#60a5fa' },
      encoding: {
        x: { field: 'turns', type: 'quantitative', title: 'Turns to finish' },
        y: { field: 'games', type: 'quantitative', title: 'Games' },
        tooltip: [{ field: 'turns', title: 'Turns' }, { field: 'games', title: 'Games' }],
      },
    },
    {
      data: { values: [{ average }] },
      mark: { type: 'rule', color: '#dc2626', strokeWidth: 2 },
      encoding: { x: { field: 'average', type: 'quantitative' } },
    },
    {
      data: { values: [{ average }] },
      mark: { type: 'text', color: '#dc2626', align: 'left', dx: 6, fontWeight: 'bold' },
      encoding: {
        x: { field: 'average', type: 'quantitative' },
        y: { value: 12 },
        text: { value: `Average: ${average.toFixed(1)} turns` },
      },
    },
  ],
};
